class Job {
  constructor(cfg, forceFrom) {
    this.job_id = `job-${nowIso().replace(/[-:T]/g, '').slice(0, 12)}-${String(S.nextRunNo++).padStart(2, '0')}`;
    this.report_id = cfg.report_id;
    this.cfg = cfg;
    this.forceFrom = forceFrom;
    this.status = 'running';
    this.started_at = nowIso();
    this.ended_at = null;
    this.cost_usd = 0;
    this.tokens = { in: 0, out: 0 };
    this.stages = STAGE_NAMES.map(n => ({ name: n, status: 'pending' }));
    this.messages = [];
    this.listeners = new Set();
    this.cancelRequested = false;
    this.timer = null;
    this.plan = this.buildPlan();
    this.idx = 0;
    this.step = 0;
    this.timer = setTimeout(() => this.tick(), 400);
  }
  buildPlan() {
    const layers = new Set(this.cfg.layers || []);
    const blind = !!(this.cfg.options && this.cfg.options.blind_rerun && this.cfg.options.blind_rerun.enabled);
    const forceIdx = this.forceFrom ? STAGE_NAMES.indexOf(this.forceFrom) : -1;
    return STAGE_NAMES.map((name, i) => {
      if (name === 'intake') return { name, mode: 'skip', why: '접수는 업로드 시 완료' };
      const layer = LAYER_OF[name];
      if (layer && !layers.has(layer)) return { name, mode: 'skip', why: `${layer} 층이 선택되지 않음` };
      if ((name === 'brief' || name === 'blind') && !blind) return { name, mode: 'skip', why: '블라인드 재수행 꺼짐' };
      const forced = forceIdx >= 0 && i >= forceIdx;
      if (!forced && name !== 'report' && name !== 'critic' && hasOutputs(this.report_id, name)) return { name, mode: 'skip', why: `산출물 ${STAGE_OUTPUT[name]} 있음(재개)` };
      return { name, mode: 'run', script: STAGE_SCRIPT[name] || ['처리'] };
    });
  }
  setStage(name, status) { const s = this.stages.find(x => x.name === name); if (s) s.status = status; }
  emit(ev) {
    ev = Object.assign({ job_id: this.job_id, report_id: this.report_id, ts: nowIso() }, ev);
    this.messages.push(ev); if (this.messages.length > 20) this.messages.shift();
    for (const l of this.listeners) { try { l(ev); } catch (_) { /* ignore */ } }
  }
  tick() {
    if (this.status !== 'running') return;
    const item = this.plan[this.idx];
    if (!item) { this.finish('done'); return; }
    if (item.mode === 'skip') {
      this.setStage(item.name, 'skipped');
      this.emit({ stage: item.name, status: 'skipped', step: 0, message: `건너뜀 — ${item.why}`, tokens: { in: 0, out: 0 }, cost_usd: 0 });
      this.idx++; this.step = 0;
      this.timer = setTimeout(() => this.tick(), 250);
      return;
    }
    if (this.step === 0) {
      if (this.cancelRequested) { this.finish('cancelled'); return; }
      this.setStage(item.name, 'running');
      this.emit({ stage: item.name, status: 'running', step: 0, message: `${item.name} 단계 시작`, tokens: { in: 0, out: 0 }, cost_usd: 0 });
      this.step = 1;
      this.timer = setTimeout(() => this.tick(), 500);
      return;
    }
    const line = item.script[this.step - 1];
    if (line !== undefined) {
      const isLlm = /LLM 호출/.test(line);
      const tin = isLlm ? 3000 + Math.floor(Math.random() * 9000) : 0;
      const tout = isLlm ? 400 + Math.floor(Math.random() * 2000) : 0;
      const cost = +(tin * 2.5e-6 + tout * 1.0e-5).toFixed(5);
      this.tokens.in += tin; this.tokens.out += tout; this.cost_usd = +(this.cost_usd + cost).toFixed(5);
      this.emit({ stage: item.name, status: 'running', step: this.step, message: line, tokens: { in: tin, out: tout }, cost_usd: cost });
      this.step++;
      this.timer = setTimeout(() => this.tick(), 450 + Math.random() * 500);
      return;
    }
    this.setStage(item.name, 'done');
    this.emit({ stage: item.name, status: 'done', step: this.step, message: `${item.name} 완료`, tokens: { in: 0, out: 0 }, cost_usd: 0 });
    this.idx++; this.step = 0;
    this.timer = setTimeout(() => this.tick(), 300);
  }
  finish(status) {
    this.status = status; this.ended_at = nowIso();
    for (const s of this.stages) if (s.status === 'running') s.status = status === 'done' ? 'done' : status;
    if (status === 'done') {
      const r = S.reports.find(x => x.id === this.report_id);
      if (r) {
        const L = this.cfg.layers || [];
        r.maturity = L.includes('L2') ? 'L2' : L.includes('L1') ? 'L1' : 'L0';
        r.updated_at = nowIso();
        if (this.report_id !== 'R01' && !r.summary) r.summary = { '동일': 0, '강화': 0, '부분수정': 0, '약화': 0, '뒤집힘': 0, '신규결론': 0, '판정불가': 0, '잠정': 0 };
      }
    }
    this.emit({ stage: 'pipeline', status, step: 0, message: status === 'done' ? `파이프라인 종료 · 비용 $${this.cost_usd.toFixed(4)}` : status === 'cancelled' ? '취소 요청으로 단계 경계에서 중단' : '실패로 중단', tokens: { in: 0, out: 0 }, cost_usd: 0 });
    for (const l of this.listeners) { try { l({ __close: true }); } catch (_) { /* ignore */ } }
  }
  snapshot() {
    return { job_id: this.job_id, report_id: this.report_id, status: this.status, started_at: this.started_at, ended_at: this.ended_at,
      cost_usd: this.cost_usd, tokens: Object.assign({}, this.tokens), stages: this.stages.map(s => Object.assign({}, s)), messages: this.messages.slice(-20) };
  }
}

/* ---------- 가짜 EventSource ---------- */
class MockEventSource {
  constructor(url) {
    this.url = String(url);
    this.readyState = 0; // CONNECTING
    this.onmessage = null; this.onerror = null; this.onopen = null;
    this._handlers = {};
    const m = this.url.match(/\/api\/runs\/([^/]+)\/events/);
    const job = m && S.jobs[m[1]];
    this._job = job || null;
    setTimeout(() => {
      if (!job) { this.readyState = 2; if (this.onerror) this.onerror(new Event('error')); return; }
      this.readyState = 1;
      if (this.onopen) this.onopen(new Event('open'));
      this._listener = ev => {
        if (ev.__close) { this.readyState = 2; job.listeners.delete(this._listener); if (this.onerror) this.onerror(new Event('error')); return; }
        // 서버와 같게 기본 message 이벤트로만 보낸다(event: progress 는 쓰지 않음)
        const e = new MessageEvent('message', { data: JSON.stringify(ev) });
        if (this.onmessage) this.onmessage(e);
        (this._handlers.message || []).forEach(h => h(e));
      };
      job.listeners.add(this._listener);
      if (job.status !== 'running') this._listener({ __close: true });
    }, 60);
  }
  addEventListener(type, fn) { (this._handlers[type] = this._handlers[type] || []).push(fn); }
  removeEventListener(type, fn) { this._handlers[type] = (this._handlers[type] || []).filter(f => f !== fn); }
  close() { this.readyState = 2; if (this._job && this._listener) this._job.listeners.delete(this._listener); }
}
MockEventSource.CONNECTING = 0; MockEventSource.OPEN = 1; MockEventSource.CLOSED = 2;

